"use strict";
const http2 = require("node:http2");
const { createGrpcServer } = require("./service/grpc_server.js");
const wire = require("./service/wire.js");

(async () => {
  const server = createGrpcServer();
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  const port = server.address().port;
  const session = http2.connect(`http://127.0.0.1:${port}`);
  const stream = session.request({
    ":method": "POST",
    ":path": "/energy.v1.EnergyService/GetReading",
    "content-type": "application/grpc",
    "te": "trailers",
  });
  stream.on("response", (h) => console.log("RESPONSE", h));
  stream.on("trailers", (t) => console.log("TRAILERS", t));
  stream.on("end", () => {
    console.log("END");
    session.close();
    server.close();
  });
  stream.end(wire.encodeFrame(wire.encodeGetReadingRequest({ siteId: "site-zz" })));
})();

