test("StreamReadings sends one sub-16KiB gRPC frame per Reading", async () => {
  const result = await rawCall(
    PATHS.streamReadings,
    wire.encodeFrame(wire.encodeStreamReadingsRequest({ siteId: "site-a" })),
  );

  assert.equal(result.trailers["grpc-status"], "0");
  const body = result.body ?? Buffer.alloc(0);
  const frames = [];
  let offset = 0;
  while (offset < body.length) {
    assert.ok(offset + wire.FRAME_HEADER_BYTES <= body.length, "truncated frame header");
    assert.equal(body[offset], 0, "compression flag must be zero");
    const length = body.readUInt32BE(offset + 1);
    assert.ok(length < 16 * 1024, `frame of ${String(length)} bytes exceeds the 16 KiB ceiling`);
    const start = offset + wire.FRAME_HEADER_BYTES;
    const end = start + length;
    assert.ok(end <= body.length, "truncated frame payload");
    // Decoding one frame as exactly one message proves no frame batches readings.
    frames.push(wire.decodeFrame(body.subarray(offset, end)));
    offset = end;
  }

  assert.equal(offset, body.length);
  assert.equal(frames.length, 6);
  assert.deepEqual(
    frames.map((frame) => wire.decodeReading(frame).atMs),
    [1762300000000, 1762300060000, 1762300120000, 1762300180000, 1762300240000, 1762300300000],
  );
});

