test("a measured 12KiB Reading fits in one sub-16KiB frame", () => {
  const reading = {
    siteId: `site-${"x".repeat(12000)}`,
    watts: 4120,
    atMs: 1762300000000,
  };
  const frame = wire.encodeFrame(wire.encodeReading(reading));
  assert.ok(frame.length < 16 * 1024, `frame of ${String(frame.length)} bytes exceeds 16 KiB`);
  assert.deepEqual(wire.decodeReading(wire.decodeFrame(frame)), reading);
});

