    console.log("streamed atMs:", JSON.stringify(streamed));
    try {
      await client.getReading("site-zz");
    } catch (error) {
      console.log("unknown site error:", error.message, "status:", error.grpcStatus);
    }
    try {
      await client.getReadings("site-a", -1);
    } catch (error) {
      console.log("negative limit error:", error.message, "status:", error.grpcStatus);
    }
  } finally {
    client.close();
    await new Promise((resolve) => server.close(resolve));
  }
})().catch((error) => { console.error(error); process.exitCode = 1; });
